      "achados": [
        {
          "proposicao": "O sistema de tocha é apresentado como parte do sistema de alívio de pressão de plantas industriais, destinado à eliminação de gás excedente por combustão, com enquadramento técnico ligado à segurança e compatibilidade ambiental.",
          "trechos": [
            "E6055ba901a96c66f:0:694",
            "E6055ba901a96c66f:694:1391"
          ],
          "condicoes": [
            "aplicação ao contexto de sistemas de tocha em unidades industriais",
            "definição apoiada em normas citadas no texto"
          ],
          "limites": [
            "o trecho é descritivo e conceitual",
            "não traz critérios operacionais detalhados para partida, upset, ESD, inspeção ou descomissionamento"
          ]
        },
        {
          "proposicao": "As normas citadas no texto associam sistemas de tocha à análise de causas de sobrepressão, especificação de taxas de alívio e seleção/projeto de sistemas de eliminação de gás, incluindo seus componentes principais.",
          "trechos": [
            "E6055ba901a96c66f:694:1391",
            "E6055ba901a96c66f:1391:2089"
          ],
          "condicoes": [
            "no contexto de projeto e análise de sistemas de alívio e flare",
            "referido a orientações normativas mencionadas pelo autor"
          ],
          "limites": [
            "o texto não explicita os critérios numéricos nem os métodos de cálculo",
            "não diferencia, nesses trechos, requisitos específicos para FPSO versus outras plantas"
          ]
        },
        {
          "proposicao": "Um esquema típico de sistema flare inclui, no mínimo, vaso de separação de líquido, torre, selo e medidor de vazão, enquanto outros equipamentos fazem o controle automático do sistema.",
          "trechos": [
            "E6055ba901a96c66f:1391:2089",
            "E6055ba901a96c66f:2089:2287"
          ],
          "condicoes": [
            "apresentado como esquema típico",
            "voltado à descrição de arquitetura funcional do sistema"
          ],
          "limites": [
            "a lista não deve ser tomada como exaustiva para qualquer instalação",
            "não há detalhamento de compatibilidade, manutenção ou inspeção de cada componente"
          ]
        }
      ]
    },
