      "achados": [
        {
          "proposicao": "As auditorias temáticas de 2021 da ANP incluíram avaliação de sistema de contenção primária e sistema de alívio e despressurização em instalações marítimas, indicando utilidade desse recorte para o ciclo de vida operacional desses sistemas.",
          "trechos": [
            "Ef470663ef97661f0:0:696"
          ],
          "condicoes": [
            "no contexto das auditorias temáticas realizadas em 2021",
            "referido às instalações auditadas no relatório"
          ],
          "limites": [
            "não constitui regra universal para todas as instalações",
            "o trecho não detalha métodos de auditoria nem critérios completos"
          ]
        },
        {
          "proposicao": "Na avaliação dos sistemas de alívio e despressurização, foram considerados integridade dos componentes, dimensionamento, condições atuais de operação e observância de limites operacionais como PMTA.",
          "trechos": [
            "Ef470663ef97661f0:696:1391",
            "Ef470663ef97661f0:1391:2091"
          ],
          "condicoes": [
            "no escopo das auditorias descritas",
            "abrangendo shutdown, blowdown, PSV, flaring & venting e tubulações"
          ],
          "limites": [
            "o relatório resume focos de avaliação, sem desenvolver os critérios técnicos completos",
            "não informa neste trecho como cada verificação foi executada"
          ]
        },
        {
          "proposicao": "O subdimensionamento do sistema de flare apareceu como principal desvio encontrado nas auditorias descritas, associado ao risco de não suportar a vazão de despressurização quando demandado.",
          "trechos": [
            "Ef470663ef97661f0:1391:2091",
            "Ef470663ef97661f0:2091:2347"
          ],
          "condicoes": [
            "resultado observado nas instalações auditadas",
            "quando houver demanda de despressurização"
          ],
          "limites": [
            "o achado empírico é restrito ao conjunto auditado citado no relatório",
            "o trecho disponível está truncado e não expõe a continuidade sobre cenários de despressurização"
          ]
        }
      ]
    },
    {
      "id": "Ed151559ab78cb84a",
